CREATE COLUMN TABLE "TEST_AP"."RLS1" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineID" INTEGER CS_INT NOT NULL , "SrcObjType" NVARCHAR(20) NOT NULL , "SrcArr" SMALLINT CS_INT NOT NULL , "SrcFld" NVARCHAR(21) NOT NULL , PRIMARY KEY ("AbsEntry", "LineID")) UNLOAD PRIORITY 5  AUTO MERGE ;
